#!/usr/bin/env bun
/**
 * Simple JSON validator utility script.
 * Reads JSON input from stdin and validates it.
 *
 * Usage:
 *   echo '{"valid": "json"}' | bun run src/validate-json.ts
 *   cat file.json | bun run src/validate-json.ts
 *
 * Exit codes:
 *   0 - Valid JSON
 *   1 - Invalid JSON or error
 */

/**
 * Validate a JSON string.
 * @param input - The string to validate as JSON
 * @returns An object with valid flag and parsed data or error message
 */
export function validateJson(input: string): {
  valid: boolean;
  data?: unknown;
  error?: string;
} {
  const trimmed = input.trim();

  if (trimmed === "") {
    return { valid: false, error: "Empty input" };
  }

  try {
    const data = JSON.parse(trimmed);
    return { valid: true, data };
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown parsing error";
    return { valid: false, error: message };
  }
}

/**
 * Read all data from stdin.
 */
async function readStdin(): Promise<string> {
  const chunks: string[] = [];
  const reader = Bun.stdin.stream().getReader();

  const decoder = new TextDecoder();

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(decoder.decode(value, { stream: true }));
  }

  // Flush any remaining bytes
  chunks.push(decoder.decode());

  return chunks.join("");
}

/**
 * Main entry point.
 */
async function main(): Promise<void> {
  const input = await readStdin();
  const result = validateJson(input);

  if (result.valid) {
    console.log("Valid JSON");
    process.exit(0);
  } else {
    console.error(`Invalid JSON: ${result.error}`);
    process.exit(1);
  }
}

// Run main when executed directly
main();

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("validates valid JSON object", () => {
    const result = validateJson('{"key": "value"}');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ key: "value" });
    expect(result.error).toBeUndefined();
  });

  test("validates valid JSON array", () => {
    const result = validateJson("[1, 2, 3]");
    expect(result.valid).toBe(true);
    expect(result.data).toEqual([1, 2, 3]);
  });

  test("validates valid JSON primitive string", () => {
    const result = validateJson('"hello"');
    expect(result.valid).toBe(true);
    expect(result.data).toBe("hello");
  });

  test("validates valid JSON primitive number", () => {
    const result = validateJson("42");
    expect(result.valid).toBe(true);
    expect(result.data).toBe(42);
  });

  test("validates valid JSON with whitespace", () => {
    const result = validateJson('  \n{"key": "value"}\n  ');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ key: "value" });
  });

  test("rejects empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("rejects whitespace-only input", () => {
    const result = validateJson("   \n\t  ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("rejects invalid JSON syntax", () => {
    const result = validateJson("{invalid}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects unclosed brackets", () => {
    const result = validateJson('{"key": "value"');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("rejects trailing comma", () => {
    const result = validateJson('{"key": "value",}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });
});

