/**
 * Ultra-performant JSON validation module.
 *
 * Performance optimizations:
 * - Early exit on first validation error (fail-fast)
 * - Pre-compiled schema validators for repeated use
 * - Minimal object allocation during validation
 * - Direct type checking without intermediate conversions
 */

/**
 * JSON Schema type definitions for validation.
 */
export type JsonSchemaType =
  | "string"
  | "number"
  | "boolean"
  | "null"
  | "array"
  | "object";

/**
 * Schema definition for JSON validation.
 */
export interface JsonSchema {
  type?: JsonSchemaType | JsonSchemaType[];
  properties?: Record<string, JsonSchema>;
  required?: string[];
  items?: JsonSchema;
  minLength?: number;
  maxLength?: number;
  minimum?: number;
  maximum?: number;
  pattern?: string;
  enum?: unknown[];
  additionalProperties?: boolean | JsonSchema;
}

/**
 * Validation result with error details.
 */
export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

/**
 * Validation error with path and message.
 */
export interface ValidationError {
  path: string;
  message: string;
  value?: unknown;
}

/**
 * Pre-compiled validator function type.
 */
export type CompiledValidator = (data: unknown) => ValidationResult;

/**
 * Validates JSON string syntax quickly.
 * Uses native JSON.parse with minimal overhead.
 *
 * @param input - JSON string to validate
 * @returns Validation result with parsed data or error
 */
export function validateJsonSyntax(input: string): {
  valid: boolean;
  data?: unknown;
  error?: string;
} {
  try {
    const data = JSON.parse(input);
    return { valid: true, data };
  } catch (e) {
    const message = e instanceof Error ? e.message : "Invalid JSON";
    return { valid: false, error: message };
  }
}

/**
 * Gets the JSON type of a value.
 * Optimized for speed with direct typeof checks.
 */
function getJsonType(value: unknown): JsonSchemaType | "undefined" {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  const t = typeof value;
  if (t === "string" || t === "number" || t === "boolean" || t === "object") {
    return t as JsonSchemaType;
  }
  return "undefined";
}

/**
 * Checks if a value matches expected type(s).
 */
function matchesType(
  value: unknown,
  expectedType: JsonSchemaType | JsonSchemaType[]
): boolean {
  const actualType = getJsonType(value);
  if (Array.isArray(expectedType)) {
    return expectedType.includes(actualType as JsonSchemaType);
  }
  return actualType === expectedType;
}

/**
 * Validates data against a JSON schema.
 * Uses fail-fast approach for performance.
 *
 * @param data - Data to validate
 * @param schema - JSON schema to validate against
 * @param path - Current path for error reporting (internal)
 * @returns Validation result
 */
export function validateSchema(
  data: unknown,
  schema: JsonSchema,
  path = "$"
): ValidationResult {
  const errors: ValidationError[] = [];

  // Type validation (fail-fast)
  if (schema.type !== undefined) {
    if (!matchesType(data, schema.type)) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Expected type ${JSON.stringify(schema.type)}, got ${getJsonType(data)}`,
            value: data,
          },
        ],
      };
    }
  }

  // Enum validation (fail-fast)
  if (schema.enum !== undefined) {
    const found = schema.enum.some(
      (e) => JSON.stringify(e) === JSON.stringify(data)
    );
    if (!found) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Value must be one of: ${JSON.stringify(schema.enum)}`,
            value: data,
          },
        ],
      };
    }
  }

  // String validations
  if (typeof data === "string") {
    if (schema.minLength !== undefined && data.length < schema.minLength) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `String length ${data.length} is less than minimum ${schema.minLength}`,
            value: data,
          },
        ],
      };
    }
    if (schema.maxLength !== undefined && data.length > schema.maxLength) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `String length ${data.length} exceeds maximum ${schema.maxLength}`,
            value: data,
          },
        ],
      };
    }
    if (schema.pattern !== undefined) {
      const regex = new RegExp(schema.pattern);
      if (!regex.test(data)) {
        return {
          valid: false,
          errors: [
            {
              path,
              message: `String does not match pattern: ${schema.pattern}`,
              value: data,
            },
          ],
        };
      }
    }
  }

  // Number validations
  if (typeof data === "number") {
    if (schema.minimum !== undefined && data < schema.minimum) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Number ${data} is less than minimum ${schema.minimum}`,
            value: data,
          },
        ],
      };
    }
    if (schema.maximum !== undefined && data > schema.maximum) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Number ${data} exceeds maximum ${schema.maximum}`,
            value: data,
          },
        ],
      };
    }
  }

  // Array validation
  if (Array.isArray(data) && schema.items !== undefined) {
    for (let i = 0; i < data.length; i++) {
      const itemResult = validateSchema(data[i], schema.items, `${path}[${i}]`);
      if (!itemResult.valid) {
        return itemResult; // Fail-fast
      }
    }
  }

  // Object validation
  if (
    typeof data === "object" &&
    data !== null &&
    !Array.isArray(data) &&
    schema.properties !== undefined
  ) {
    const obj = data as Record<string, unknown>;

    // Required properties check
    if (schema.required !== undefined) {
      for (const key of schema.required) {
        if (!(key in obj)) {
          return {
            valid: false,
            errors: [
              {
                path: `${path}.${key}`,
                message: `Required property "${key}" is missing`,
              },
            ],
          };
        }
      }
    }

    // Property validation
    for (const [key, propSchema] of Object.entries(schema.properties)) {
      if (key in obj) {
        const propResult = validateSchema(obj[key], propSchema, `${path}.${key}`);
        if (!propResult.valid) {
          return propResult; // Fail-fast
        }
      }
    }

    // Additional properties check
    if (schema.additionalProperties === false) {
      const allowedKeys = new Set(Object.keys(schema.properties));
      for (const key of Object.keys(obj)) {
        if (!allowedKeys.has(key)) {
          return {
            valid: false,
            errors: [
              {
                path: `${path}.${key}`,
                message: `Additional property "${key}" is not allowed`,
                value: obj[key],
              },
            ],
          };
        }
      }
    }
  }

  return { valid: true, errors };
}

/**
 * Compiles a schema into a reusable validator function.
 * Use this when validating multiple items against the same schema.
 *
 * @param schema - JSON schema to compile
 * @returns Compiled validator function
 */
export function compileSchema(schema: JsonSchema): CompiledValidator {
  // Pre-compile regex patterns for performance
  const compiledPatterns = new Map<string, RegExp>();
  function extractPatterns(s: JsonSchema): void {
    if (s.pattern) {
      compiledPatterns.set(s.pattern, new RegExp(s.pattern));
    }
    if (s.properties) {
      for (const prop of Object.values(s.properties)) {
        extractPatterns(prop);
      }
    }
    if (s.items) {
      extractPatterns(s.items);
    }
  }
  extractPatterns(schema);

  // Return optimized validator that uses pre-compiled patterns
  return (data: unknown): ValidationResult => {
    return validateSchemaWithPatterns(data, schema, "$", compiledPatterns);
  };
}

/**
 * Internal validation function with pre-compiled patterns.
 */
function validateSchemaWithPatterns(
  data: unknown,
  schema: JsonSchema,
  path: string,
  patterns: Map<string, RegExp>
): ValidationResult {
  const errors: ValidationError[] = [];

  // Type validation (fail-fast)
  if (schema.type !== undefined) {
    if (!matchesType(data, schema.type)) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Expected type ${JSON.stringify(schema.type)}, got ${getJsonType(data)}`,
            value: data,
          },
        ],
      };
    }
  }

  // Enum validation (fail-fast)
  if (schema.enum !== undefined) {
    const found = schema.enum.some(
      (e) => JSON.stringify(e) === JSON.stringify(data)
    );
    if (!found) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Value must be one of: ${JSON.stringify(schema.enum)}`,
            value: data,
          },
        ],
      };
    }
  }

  // String validations with pre-compiled patterns
  if (typeof data === "string") {
    if (schema.minLength !== undefined && data.length < schema.minLength) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `String length ${data.length} is less than minimum ${schema.minLength}`,
            value: data,
          },
        ],
      };
    }
    if (schema.maxLength !== undefined && data.length > schema.maxLength) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `String length ${data.length} exceeds maximum ${schema.maxLength}`,
            value: data,
          },
        ],
      };
    }
    if (schema.pattern !== undefined) {
      const regex = patterns.get(schema.pattern) ?? new RegExp(schema.pattern);
      if (!regex.test(data)) {
        return {
          valid: false,
          errors: [
            {
              path,
              message: `String does not match pattern: ${schema.pattern}`,
              value: data,
            },
          ],
        };
      }
    }
  }

  // Number validations
  if (typeof data === "number") {
    if (schema.minimum !== undefined && data < schema.minimum) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Number ${data} is less than minimum ${schema.minimum}`,
            value: data,
          },
        ],
      };
    }
    if (schema.maximum !== undefined && data > schema.maximum) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Number ${data} exceeds maximum ${schema.maximum}`,
            value: data,
          },
        ],
      };
    }
  }

  // Array validation
  if (Array.isArray(data) && schema.items !== undefined) {
    for (let i = 0; i < data.length; i++) {
      const itemResult = validateSchemaWithPatterns(
        data[i],
        schema.items,
        `${path}[${i}]`,
        patterns
      );
      if (!itemResult.valid) {
        return itemResult; // Fail-fast
      }
    }
  }

  // Object validation
  if (
    typeof data === "object" &&
    data !== null &&
    !Array.isArray(data) &&
    schema.properties !== undefined
  ) {
    const obj = data as Record<string, unknown>;

    // Required properties check
    if (schema.required !== undefined) {
      for (const key of schema.required) {
        if (!(key in obj)) {
          return {
            valid: false,
            errors: [
              {
                path: `${path}.${key}`,
                message: `Required property "${key}" is missing`,
              },
            ],
          };
        }
      }
    }

    // Property validation
    for (const [key, propSchema] of Object.entries(schema.properties)) {
      if (key in obj) {
        const propResult = validateSchemaWithPatterns(
          obj[key],
          propSchema,
          `${path}.${key}`,
          patterns
        );
        if (!propResult.valid) {
          return propResult; // Fail-fast
        }
      }
    }

    // Additional properties check
    if (schema.additionalProperties === false) {
      const allowedKeys = new Set(Object.keys(schema.properties));
      for (const key of Object.keys(obj)) {
        if (!allowedKeys.has(key)) {
          return {
            valid: false,
            errors: [
              {
                path: `${path}.${key}`,
                message: `Additional property "${key}" is not allowed`,
                value: obj[key],
              },
            ],
          };
        }
      }
    }
  }

  return { valid: true, errors };
}

/**
 * Validates JSON string and then validates against schema.
 * Convenience function combining syntax and schema validation.
 *
 * @param input - JSON string to validate
 * @param schema - Optional schema to validate against
 * @returns Validation result
 */
export function validateJson(
  input: string,
  schema?: JsonSchema
): ValidationResult {
  const syntaxResult = validateJsonSyntax(input);

  if (!syntaxResult.valid) {
    return {
      valid: false,
      errors: [
        {
          path: "$",
          message: `JSON syntax error: ${syntaxResult.error}`,
        },
      ],
    };
  }

  if (schema === undefined) {
    return { valid: true, errors: [] };
  }

  return validateSchema(syntaxResult.data, schema);
}

/**
 * Batch validation for multiple JSON items.
 * Optimized for validating arrays of similar data.
 *
 * @param items - Array of data items to validate
 * @param schema - Schema to validate against
 * @returns Array of validation results (same order as input)
 */
export function validateBatch(
  items: unknown[],
  schema: JsonSchema
): ValidationResult[] {
  const validator = compileSchema(schema);
  return items.map(validator);
}

/**
 * Fast check if a value is valid JSON.
 * Returns boolean only, no error details.
 * Use this when you only need a yes/no answer.
 *
 * @param input - String to check
 * @returns true if valid JSON, false otherwise
 */
export function isValidJson(input: string): boolean {
  try {
    JSON.parse(input);
    return true;
  } catch {
    return false;
  }
}

/**
 * Fast check if data matches a schema.
 * Returns boolean only, no error details.
 * Use this when you only need a yes/no answer.
 *
 * @param data - Data to validate
 * @param schema - Schema to validate against
 * @returns true if valid, false otherwise
 */
export function isValid(data: unknown, schema: JsonSchema): boolean {
  return validateSchema(data, schema).valid;
}

