/**
 * Ultra-performant JSON validation module.
 *
 * Performance optimizations:
 * - Early exit on first validation error (fail-fast)
 * - Pre-compiled schema validators for repeated use
 * - Minimal object allocation during validation
 * - Direct type checking without intermediate conversions
 */

/**
 * JSON Schema type definitions for validation.
 */
export type JsonSchemaType =
  | "string"
  | "number"
  | "boolean"
  | "null"
  | "array"
  | "object";

/**
 * Schema definition for JSON validation.
 */
export interface JsonSchema {
  type?: JsonSchemaType | JsonSchemaType[];
  properties?: Record<string, JsonSchema>;
  required?: string[];
  items?: JsonSchema;
  minLength?: number;
  maxLength?: number;
  minimum?: number;
  maximum?: number;
  pattern?: string;
  enum?: unknown[];
  additionalProperties?: boolean | JsonSchema;
}

/**
 * Validation result with error details.
 */
export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

/**
 * Validation error with path and message.
 */
export interface ValidationError {
  path: string;
  message: string;
  value?: unknown;
}

/**
 * Pre-compiled validator function type.
 */
export type CompiledValidator = (data: unknown) => ValidationResult;

/**
 * Validates JSON string syntax quickly.
 * Uses native JSON.parse with minimal overhead.
 *
 * @param input - JSON string to validate
 * @returns Validation result with parsed data or error
 */
export function validateJsonSyntax(input: string): {
  valid: boolean;
  data?: unknown;
  error?: string;
} {
  try {
    const data = JSON.parse(input);
    return { valid: true, data };
  } catch (e) {
    const message = e instanceof Error ? e.message : "Invalid JSON";
    return { valid: false, error: message };
  }
}

/**
 * Gets the JSON type of a value.
 * Optimized for speed with direct typeof checks.
 */
function getJsonType(value: unknown): JsonSchemaType | "undefined" {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  const t = typeof value;
  if (t === "string" || t === "number" || t === "boolean" || t === "object") {
    return t as JsonSchemaType;
  }
  return "undefined";
}

/**
 * Checks if a value matches expected type(s).
 */
function matchesType(
  value: unknown,
  expectedType: JsonSchemaType | JsonSchemaType[]
): boolean {
  const actualType = getJsonType(value);
  if (Array.isArray(expectedType)) {
    return expectedType.includes(actualType as JsonSchemaType);
  }
  return actualType === expectedType;
}

/**
 * Validates data against a JSON schema.
 * Uses fail-fast approach for performance.
 *
 * @param data - Data to validate
 * @param schema - JSON schema to validate against
 * @param path - Current path for error reporting (internal)
 * @returns Validation result
 */
export function validateSchema(
  data: unknown,
  schema: JsonSchema,
  path = "$"
): ValidationResult {
  const errors: ValidationError[] = [];

  // Type validation (fail-fast)
  if (schema.type !== undefined) {
    if (!matchesType(data, schema.type)) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Expected type ${JSON.stringify(schema.type)}, got ${getJsonType(data)}`,
            value: data,
          },
        ],
      };
    }
  }

  // Enum validation (fail-fast)
  if (schema.enum !== undefined) {
    const found = schema.enum.some(
      (e) => JSON.stringify(e) === JSON.stringify(data)
    );
    if (!found) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Value must be one of: ${JSON.stringify(schema.enum)}`,
            value: data,
          },
        ],
      };
    }
  }

  // String validations
  if (typeof data === "string") {
    if (schema.minLength !== undefined && data.length < schema.minLength) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `String length ${data.length} is less than minimum ${schema.minLength}`,
            value: data,
          },
        ],
      };
    }
    if (schema.maxLength !== undefined && data.length > schema.maxLength) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `String length ${data.length} exceeds maximum ${schema.maxLength}`,
            value: data,
          },
        ],
      };
    }
    if (schema.pattern !== undefined) {
      const regex = new RegExp(schema.pattern);
      if (!regex.test(data)) {
        return {
          valid: false,
          errors: [
            {
              path,
              message: `String does not match pattern: ${schema.pattern}`,
              value: data,
            },
          ],
        };
      }
    }
  }

  // Number validations
  if (typeof data === "number") {
    if (schema.minimum !== undefined && data < schema.minimum) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Number ${data} is less than minimum ${schema.minimum}`,
            value: data,
          },
        ],
      };
    }
    if (schema.maximum !== undefined && data > schema.maximum) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Number ${data} exceeds maximum ${schema.maximum}`,
            value: data,
          },
        ],
      };
    }
  }

  // Array validation
  if (Array.isArray(data) && schema.items !== undefined) {
    for (let i = 0; i < data.length; i++) {
      const itemResult = validateSchema(data[i], schema.items, `${path}[${i}]`);
      if (!itemResult.valid) {
        return itemResult; // Fail-fast
      }
    }
  }

  // Object validation
  if (
    typeof data === "object" &&
    data !== null &&
    !Array.isArray(data) &&
    schema.properties !== undefined
  ) {
    const obj = data as Record<string, unknown>;

    // Required properties check
    if (schema.required !== undefined) {
      for (const key of schema.required) {
        if (!(key in obj)) {
          return {
            valid: false,
            errors: [
              {
                path: `${path}.${key}`,
                message: `Required property "${key}" is missing`,
              },
            ],
          };
        }
      }
    }

    // Property validation
    for (const [key, propSchema] of Object.entries(schema.properties)) {
      if (key in obj) {
        const propResult = validateSchema(obj[key], propSchema, `${path}.${key}`);
        if (!propResult.valid) {
          return propResult; // Fail-fast
        }
      }
    }

    // Additional properties check
    if (schema.additionalProperties === false) {
      const allowedKeys = new Set(Object.keys(schema.properties));
      for (const key of Object.keys(obj)) {
        if (!allowedKeys.has(key)) {
          return {
            valid: false,
            errors: [
              {
                path: `${path}.${key}`,
                message: `Additional property "${key}" is not allowed`,
                value: obj[key],
              },
            ],
          };
        }
      }
    }
  }

  return { valid: true, errors };
}

/**
 * Compiles a schema into a reusable validator function.
 * Use this when validating multiple items against the same schema.
 *
 * @param schema - JSON schema to compile
 * @returns Compiled validator function
 */
export function compileSchema(schema: JsonSchema): CompiledValidator {
  // Pre-compile regex patterns for performance
  const compiledPatterns = new Map<string, RegExp>();
  function extractPatterns(s: JsonSchema): void {
    if (s.pattern) {
      compiledPatterns.set(s.pattern, new RegExp(s.pattern));
    }
    if (s.properties) {
      for (const prop of Object.values(s.properties)) {
        extractPatterns(prop);
      }
    }
    if (s.items) {
      extractPatterns(s.items);
    }
  }
  extractPatterns(schema);

  // Return optimized validator that uses pre-compiled patterns
  return (data: unknown): ValidationResult => {
    return validateSchemaWithPatterns(data, schema, "$", compiledPatterns);
  };
}

/**
 * Internal validation function with pre-compiled patterns.
 */
function validateSchemaWithPatterns(
  data: unknown,
  schema: JsonSchema,
  path: string,
  patterns: Map<string, RegExp>
): ValidationResult {
  const errors: ValidationError[] = [];

  // Type validation (fail-fast)
  if (schema.type !== undefined) {
    if (!matchesType(data, schema.type)) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Expected type ${JSON.stringify(schema.type)}, got ${getJsonType(data)}`,
            value: data,
          },
        ],
      };
    }
  }

  // Enum validation (fail-fast)
  if (schema.enum !== undefined) {
    const found = schema.enum.some(
      (e) => JSON.stringify(e) === JSON.stringify(data)
    );
    if (!found) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Value must be one of: ${JSON.stringify(schema.enum)}`,
            value: data,
          },
        ],
      };
    }
  }

  // String validations with pre-compiled patterns
  if (typeof data === "string") {
    if (schema.minLength !== undefined && data.length < schema.minLength) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `String length ${data.length} is less than minimum ${schema.minLength}`,
            value: data,
          },
        ],
      };
    }
    if (schema.maxLength !== undefined && data.length > schema.maxLength) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `String length ${data.length} exceeds maximum ${schema.maxLength}`,
            value: data,
          },
        ],
      };
    }
    if (schema.pattern !== undefined) {
      const regex = patterns.get(schema.pattern) ?? new RegExp(schema.pattern);
      if (!regex.test(data)) {
        return {
          valid: false,
          errors: [
            {
              path,
              message: `String does not match pattern: ${schema.pattern}`,
              value: data,
            },
          ],
        };
      }
    }
  }

  // Number validations
  if (typeof data === "number") {
    if (schema.minimum !== undefined && data < schema.minimum) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Number ${data} is less than minimum ${schema.minimum}`,
            value: data,
          },
        ],
      };
    }
    if (schema.maximum !== undefined && data > schema.maximum) {
      return {
        valid: false,
        errors: [
          {
            path,
            message: `Number ${data} exceeds maximum ${schema.maximum}`,
            value: data,
          },
        ],
      };
    }
  }

  // Array validation
  if (Array.isArray(data) && schema.items !== undefined) {
    for (let i = 0; i < data.length; i++) {
      const itemResult = validateSchemaWithPatterns(
        data[i],
        schema.items,
        `${path}[${i}]`,
        patterns
      );
      if (!itemResult.valid) {
        return itemResult; // Fail-fast
      }
    }
  }

  // Object validation
  if (
    typeof data === "object" &&
    data !== null &&
    !Array.isArray(data) &&
    schema.properties !== undefined
  ) {
    const obj = data as Record<string, unknown>;

    // Required properties check
    if (schema.required !== undefined) {
      for (const key of schema.required) {
        if (!(key in obj)) {
          return {
            valid: false,
            errors: [
              {
                path: `${path}.${key}`,
                message: `Required property "${key}" is missing`,
              },
            ],
          };
        }
      }
    }

    // Property validation
    for (const [key, propSchema] of Object.entries(schema.properties)) {
      if (key in obj) {
        const propResult = validateSchemaWithPatterns(
          obj[key],
          propSchema,
          `${path}.${key}`,
          patterns
        );
        if (!propResult.valid) {
          return propResult; // Fail-fast
        }
      }
    }

    // Additional properties check
    if (schema.additionalProperties === false) {
      const allowedKeys = new Set(Object.keys(schema.properties));
      for (const key of Object.keys(obj)) {
        if (!allowedKeys.has(key)) {
          return {
            valid: false,
            errors: [
              {
                path: `${path}.${key}`,
                message: `Additional property "${key}" is not allowed`,
                value: obj[key],
              },
            ],
          };
        }
      }
    }
  }

  return { valid: true, errors };
}

/**
 * Validates JSON string and then validates against schema.
 * Convenience function combining syntax and schema validation.
 *
 * @param input - JSON string to validate
 * @param schema - Optional schema to validate against
 * @returns Validation result
 */
export function validateJson(
  input: string,
  schema?: JsonSchema
): ValidationResult {
  const syntaxResult = validateJsonSyntax(input);

  if (!syntaxResult.valid) {
    return {
      valid: false,
      errors: [
        {
          path: "$",
          message: `JSON syntax error: ${syntaxResult.error}`,
        },
      ],
    };
  }

  if (schema === undefined) {
    return { valid: true, errors: [] };
  }

  return validateSchema(syntaxResult.data, schema);
}

/**
 * Batch validation for multiple JSON items.
 * Optimized for validating arrays of similar data.
 *
 * @param items - Array of data items to validate
 * @param schema - Schema to validate against
 * @returns Array of validation results (same order as input)
 */
export function validateBatch(
  items: unknown[],
  schema: JsonSchema
): ValidationResult[] {
  const validator = compileSchema(schema);
  return items.map(validator);
}

/**
 * Fast check if a value is valid JSON.
 * Returns boolean only, no error details.
 * Use this when you only need a yes/no answer.
 *
 * @param input - String to check
 * @returns true if valid JSON, false otherwise
 */
export function isValidJson(input: string): boolean {
  try {
    JSON.parse(input);
    return true;
  } catch {
    return false;
  }
}

/**
 * Fast check if data matches a schema.
 * Returns boolean only, no error details.
 * Use this when you only need a yes/no answer.
 *
 * @param data - Data to validate
 * @param schema - Schema to validate against
 * @returns true if valid, false otherwise
 */
export function isValid(data: unknown, schema: JsonSchema): boolean {
  return validateSchema(data, schema).valid;
}

import { describe, expect, test } from "bun:test";
import {
  validateJsonSyntax,
  validateSchema,
  validateJson,
  compileSchema,
  validateBatch,
  isValidJson,
  isValid,
  type JsonSchema,
} from "./json-validator";

describe("validateJsonSyntax", () => {
  test("returns valid for correct JSON object", () => {
    const result = validateJsonSyntax('{"name": "test"}');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ name: "test" });
  });

  test("returns valid for JSON array", () => {
    const result = validateJsonSyntax("[1, 2, 3]");
    expect(result.valid).toBe(true);
    expect(result.data).toEqual([1, 2, 3]);
  });

  test("returns valid for primitive values", () => {
    expect(validateJsonSyntax('"hello"').valid).toBe(true);
    expect(validateJsonSyntax("42").valid).toBe(true);
    expect(validateJsonSyntax("true").valid).toBe(true);
    expect(validateJsonSyntax("null").valid).toBe(true);
  });

  test("returns invalid for malformed JSON", () => {
    const result = validateJsonSyntax("{invalid}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns invalid for trailing comma", () => {
    const result = validateJsonSyntax('{"a": 1,}');
    expect(result.valid).toBe(false);
  });
});

describe("validateSchema - type validation", () => {
  test("validates string type", () => {
    const schema: JsonSchema = { type: "string" };
    expect(validateSchema("hello", schema).valid).toBe(true);
    expect(validateSchema(123, schema).valid).toBe(false);
  });

  test("validates number type", () => {
    const schema: JsonSchema = { type: "number" };
    expect(validateSchema(42, schema).valid).toBe(true);
    expect(validateSchema("42", schema).valid).toBe(false);
  });

  test("validates boolean type", () => {
    const schema: JsonSchema = { type: "boolean" };
    expect(validateSchema(true, schema).valid).toBe(true);
    expect(validateSchema(false, schema).valid).toBe(true);
    expect(validateSchema("true", schema).valid).toBe(false);
  });

  test("validates null type", () => {
    const schema: JsonSchema = { type: "null" };
    expect(validateSchema(null, schema).valid).toBe(true);
    expect(validateSchema(undefined, schema).valid).toBe(false);
  });

  test("validates array type", () => {
    const schema: JsonSchema = { type: "array" };
    expect(validateSchema([1, 2, 3], schema).valid).toBe(true);
    expect(validateSchema({}, schema).valid).toBe(false);
  });

  test("validates object type", () => {
    const schema: JsonSchema = { type: "object" };
    expect(validateSchema({ a: 1 }, schema).valid).toBe(true);
    expect(validateSchema([], schema).valid).toBe(false);
  });

  test("validates union types", () => {
    const schema: JsonSchema = { type: ["string", "number"] };
    expect(validateSchema("hello", schema).valid).toBe(true);
    expect(validateSchema(42, schema).valid).toBe(true);
    expect(validateSchema(true, schema).valid).toBe(false);
  });
});

describe("validateSchema - string constraints", () => {
  test("validates minLength", () => {
    const schema: JsonSchema = { type: "string", minLength: 3 };
    expect(validateSchema("hello", schema).valid).toBe(true);
    expect(validateSchema("hi", schema).valid).toBe(false);
  });

  test("validates maxLength", () => {
    const schema: JsonSchema = { type: "string", maxLength: 5 };
    expect(validateSchema("hello", schema).valid).toBe(true);
    expect(validateSchema("hello world", schema).valid).toBe(false);
  });

  test("validates pattern", () => {
    const schema: JsonSchema = { type: "string", pattern: "^[a-z]+$" };
    expect(validateSchema("hello", schema).valid).toBe(true);
    expect(validateSchema("Hello123", schema).valid).toBe(false);
  });
});

describe("validateSchema - number constraints", () => {
  test("validates minimum", () => {
    const schema: JsonSchema = { type: "number", minimum: 0 };
    expect(validateSchema(5, schema).valid).toBe(true);
    expect(validateSchema(-1, schema).valid).toBe(false);
  });

  test("validates maximum", () => {
    const schema: JsonSchema = { type: "number", maximum: 100 };
    expect(validateSchema(50, schema).valid).toBe(true);
    expect(validateSchema(150, schema).valid).toBe(false);
  });
});

describe("validateSchema - enum validation", () => {
  test("validates enum values", () => {
    const schema: JsonSchema = { enum: ["red", "green", "blue"] };
    expect(validateSchema("red", schema).valid).toBe(true);
    expect(validateSchema("yellow", schema).valid).toBe(false);
  });

  test("validates enum with mixed types", () => {
    const schema: JsonSchema = { enum: [1, "one", true] };
    expect(validateSchema(1, schema).valid).toBe(true);
    expect(validateSchema("one", schema).valid).toBe(true);
    expect(validateSchema(true, schema).valid).toBe(true);
    expect(validateSchema(2, schema).valid).toBe(false);
  });
});

describe("validateSchema - object validation", () => {
  test("validates object properties", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        name: { type: "string" },
        age: { type: "number" },
      },
    };
    expect(validateSchema({ name: "John", age: 30 }, schema).valid).toBe(true);
    expect(validateSchema({ name: "John", age: "30" }, schema).valid).toBe(
      false
    );
  });

  test("validates required properties", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        name: { type: "string" },
        age: { type: "number" },
      },
      required: ["name"],
    };
    expect(validateSchema({ name: "John" }, schema).valid).toBe(true);
    expect(validateSchema({ age: 30 }, schema).valid).toBe(false);
  });

  test("validates additionalProperties false", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        name: { type: "string" },
      },
      additionalProperties: false,
    };
    expect(validateSchema({ name: "John" }, schema).valid).toBe(true);
    expect(validateSchema({ name: "John", extra: true }, schema).valid).toBe(
      false
    );
  });
});

describe("validateSchema - array validation", () => {
  test("validates array items", () => {
    const schema: JsonSchema = {
      type: "array",
      items: { type: "number" },
    };
    expect(validateSchema([1, 2, 3], schema).valid).toBe(true);
    expect(validateSchema([1, "two", 3], schema).valid).toBe(false);
  });

  test("validates nested object arrays", () => {
    const schema: JsonSchema = {
      type: "array",
      items: {
        type: "object",
        properties: {
          id: { type: "number" },
        },
        required: ["id"],
      },
    };
    expect(validateSchema([{ id: 1 }, { id: 2 }], schema).valid).toBe(true);
    expect(validateSchema([{ id: 1 }, { name: "test" }], schema).valid).toBe(
      false
    );
  });
});

describe("validateSchema - error reporting", () => {
  test("reports error path for nested objects", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        user: {
          type: "object",
          properties: {
            name: { type: "string" },
          },
        },
      },
    };
    const result = validateSchema({ user: { name: 123 } }, schema);
    expect(result.valid).toBe(false);
    expect(result.errors[0].path).toBe("$.user.name");
  });

  test("reports error path for array items", () => {
    const schema: JsonSchema = {
      type: "array",
      items: { type: "string" },
    };
    const result = validateSchema(["a", "b", 3], schema);
    expect(result.valid).toBe(false);
    expect(result.errors[0].path).toBe("$[2]");
  });
});

describe("validateJson", () => {
  test("validates JSON string syntax only", () => {
    const result = validateJson('{"valid": true}');
    expect(result.valid).toBe(true);
  });

  test("validates JSON string with schema", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: { valid: { type: "boolean" } },
    };
    const result = validateJson('{"valid": true}', schema);
    expect(result.valid).toBe(true);
  });

  test("returns syntax error for invalid JSON", () => {
    const result = validateJson("{invalid}");
    expect(result.valid).toBe(false);
    expect(result.errors[0].message).toContain("JSON syntax error");
  });
});

describe("compileSchema", () => {
  test("returns reusable validator function", () => {
    const schema: JsonSchema = { type: "number", minimum: 0 };
    const validate = compileSchema(schema);

    expect(validate(5).valid).toBe(true);
    expect(validate(-1).valid).toBe(false);
  });

  test("pre-compiles regex patterns for performance", () => {
    const schema: JsonSchema = {
      type: "string",
      pattern: "^[a-z]+@[a-z]+\\.[a-z]+$",
    };
    const validate = compileSchema(schema);

    expect(validate("test@example.com").valid).toBe(true);
    expect(validate("invalid").valid).toBe(false);
  });
});

describe("validateBatch", () => {
  test("validates multiple items efficiently", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        id: { type: "number" },
        name: { type: "string" },
      },
      required: ["id"],
    };

    const items = [
      { id: 1, name: "Alice" },
      { id: 2, name: "Bob" },
      { name: "Invalid" },
    ];

    const results = validateBatch(items, schema);
    expect(results[0].valid).toBe(true);
    expect(results[1].valid).toBe(true);
    expect(results[2].valid).toBe(false);
  });
});

describe("isValidJson", () => {
  test("returns true for valid JSON", () => {
    expect(isValidJson('{"a": 1}')).toBe(true);
    expect(isValidJson("[1,2,3]")).toBe(true);
    expect(isValidJson('"string"')).toBe(true);
  });

  test("returns false for invalid JSON", () => {
    expect(isValidJson("{invalid}")).toBe(false);
    expect(isValidJson("undefined")).toBe(false);
  });
});

describe("isValid", () => {
  test("returns boolean for schema validation", () => {
    const schema: JsonSchema = { type: "number", minimum: 0, maximum: 100 };
    expect(isValid(50, schema)).toBe(true);
    expect(isValid(150, schema)).toBe(false);
    expect(isValid("50", schema)).toBe(false);
  });
});

describe("performance - fail-fast behavior", () => {
  test("stops validation on first error", () => {
    const schema: JsonSchema = {
      type: "array",
      items: { type: "number", minimum: 0 },
    };
    // Should fail on first invalid item (index 1), not continue checking
    const result = validateSchema([1, -1, -2, -3], schema);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBe(1);
    expect(result.errors[0].path).toBe("$[1]");
  });
});
